/**
 * A short, non-secret label for "which secret sealed this". Derived through its own `info`, so it
 * reveals nothing about the encryption keys, and it is what lets a rotated deployment tell a token
 * it can still open from one it never could.
 */
export declare const deriveKeyId: (secret: string) => Promise<string>;
export declare const sealToken: (payload: unknown, purpose: string, secret: string) => Promise<string>;
export declare const openToken: (token: string, purpose: string, secrets: SealedSecrets) => Promise<unknown>;
